mapper.select:
SELECT A.SEQ_NO seqNo, A.GENERATE_TIME generateTime, A.FIN_PRODUCT_CODE finProductCode, A.BRANCH, A.RISK_LEVEL riskLevel, A.AJUST_RISK_LEVEL ajustRiskLevel, A.IS_LAST, A.CREATE_USER, A.CREATE_DEPT, A.CREATE_TIME, A.UPDATE_USER, A.UPDATE_TIME, B.FINPROD_ABBR finprodAbbr FROM PRD_RISK_LEVEL A LEFT JOIN FIN_PRODUCT B ON A.FIN_PRODUCT_CODE=B.FINPROD_MARKET_ID WHERE 1=1
AND A.FIN_PRODUCT_CODE=#{finProductCode}
AND TO_CHAR(A.GENERATE_TIME,'yyyy-MM-dd')>=#{startDate} AND TO_CHAR(A.GENERATE_TIME,'yyyy-MM-dd')<=#{endDate}
AND A.BRANCH=0 AND A.IS_LAST=#{isLast}

select A.FINPROD_MARKET_ID id, A.FINPROD_MARKET_ID text, A.FINPROD_ABBR col FROM FIN_PRODUCT A left JOIN FIN_PRODUCT_ADD B ON A.FINPROD_ID=B.FINPROD_ID where A.P_FINPROD_ID is null and B.ISSUE_STATUS='01' and A.FINPROD_TYPE2='F16'
and (A.FINPROD_MARKET_ID like concat('%',concat(#{search},'%')) or A.FINPROD_ABBR like concat('%',concat(#{search},'%')))
and A.FINPROD_MARKET_ID =#{initValue}

mapper.update:
UPDATE PRD_RISK_LEVEL
SET RISK_LEVEL=#{riskLevel},
    AJUST_RISK_LEVEL=#{ajustRiskLevel}
WHERE SEQ_NO=#{seqNo}

UPDATE PRD_ASSET_RISK_LEVEL
    SET AJUST_RISK_LEVEL=#{ajustRiskLevel}
WHERE SEQ_NO=#{seqNo} AND ASSET_TYPE=#{finProductCode}

mapper.select:
select  SEQ_NO seqNo
from PRD_RISK_LEVEL
where FIN_PRODUCT_CODE= #{finProductCode}
and TO_CHAR(GENERATE_TIME,'yyyy-MM-dd')=#{generateTime}
